<section class="card"><div class="section-heading"><h2>Your schedules</h2><form method="post" action="/salary/recurring/run"><?= csrf_field() ?><button class="secondary">Process due entries now</button></form></div><?php if (!$rows): ?><div class="empty"><h3>No recurring transactions yet.</h3><p>Add your own schedule below. Nothing will be recorded until its Enabled box is selected.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Schedule</th><th>Amount</th><th>Next date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= e($row['title']) ?></strong><small><?= e(ucfirst($row['kind'])) ?> · <?= e(ucfirst($row['interval'])) ?><?= $row['kind']==='expense' ? ' · '.e($row['account']).' / '.e($row['category']) : ' · Follows your current allocation rules' ?></small></td><td><?= money($row['amount']) ?></td><td><?= e($row['next_date']) ?></td><td><?= $row['active'] ? 'Enabled' : 'Paused' ?><?php if ($row['error_text']): ?><small class="error-text"><?= e($row['error_text']) ?></small><?php endif; ?></td><td><form method="post" action="/salary/recurring/<?= e($row['id']) ?>/status"><?= csrf_field() ?><input type="hidden" name="active" value="<?= $row['active'] ? '0' : '1' ?>"><button class="secondary"><?= $row['active'] ? 'Pause' : 'Enable' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="footnote">Due entries are processed while you use the app. If the app was closed on a due date, enabled schedules catch up on the next run. Deleting an automatically recorded income or expense does not recreate that same occurrence.</p></section>
<section class="card"><h2>Create a recurring schedule</h2><form class="form-grid" method="post" action="/salary/recurring"><?= csrf_field() ?><label>Title<input name="title" maxlength="150" placeholder="Your own salary or subscription" required></label><label>Kind<select name="kind"><option value="income">Income</option><option value="expense">Expense</option></select></label><label>Amount (LKR)<input name="amount" type="number" min="0.01" max="9999999999.99" step="0.01" required></label><label>First date<input name="next_date" type="date" required></label><label>Repeat<select name="interval"><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="yearly">Yearly</option><option value="daily">Daily</option></select></label><label>Income type (income only)<select name="income_type"><option value="salary">Salary</option><option value="freelance">Freelance</option><option value="business">Business</option><option value="other">Other</option></select></label><label>Expense account (expense only)<select name="account_id"><option value="">Choose for expense</option><?php foreach ($accounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label>Expense category (expense only)<select name="category_id"><option value="">Choose for expense</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label class="full"><span><input type="checkbox" name="active" value="1"> Enabled — record due entries automatically when this app is in use</span></label><div class="full"><button>Create schedule</button></div></form><p class="footnote">Create either a reminder in Financial Calendar or an automatic recurring expense for the same bill, so you do not record the same payment twice through two separate workflows.</p></section>
<section class="card"><h2>Recent generated entries</h2><?php if (!$history): ?><p class="muted">No recurring entries have been recorded.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Schedule</th><th>Occurrence date</th><th>Linked record</th></tr></thead><tbody><?php foreach ($history as $entry): ?><tr><td><?= e($entry['title']) ?><small><?= e(ucfirst($entry['kind'])) ?></small></td><td><?= e($entry['due_date']) ?></td><td><?= $entry['income_id'] ? 'Income #'.e($entry['income_id']) : ($entry['expense_id'] ? 'Expense #'.e($entry['expense_id']) : 'Record removed · occurrence kept to prevent duplication') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
